import{bQ as a,aL as s,u as t,G as n}from"./chunks/framework.DaEK0KQB.js";const u=JSON.parse('{"title":"搜索引擎使用技巧","description":"","frontmatter":{"title":"搜索引擎使用技巧","date":"2020-05-24T11:44:19.000Z","permalink":"/pages/ce818a","categories":["更多","学习"],"tags":["搜索技巧"],"author":{"name":"xugaoyi","link":"https://github.com/xugaoyi"}},"headers":[],"relativePath":"更多/学习/10.搜索引擎使用技巧.md","filePath":"更多/学习/10.搜索引擎使用技巧.md","lastUpdated":1786944735000}'),o={name:"更多/学习/10.搜索引擎使用技巧.md"};function i(r,e,p,d,l,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="搜索引擎使用技巧" tabindex="-1">搜索引擎使用技巧 <a class="header-anchor" href="#搜索引擎使用技巧" aria-label="Permalink to &quot;搜索引擎使用技巧&quot;">​</a></h1><p>搜索引擎相信大家经常在使用，但是有时候想搜某个信息时却搜出来一大堆不相关的（百度：你们都在看我干什么？）。下面我们来介绍几种搜索技巧，可以提升搜索效率，助你快速查资料，妈妈再也不担心我的学习了（&#39;妈~我真的是在找学习资料&#39;）</p><h3 id="技巧1-排除干扰项" tabindex="-1">技巧1：排除干扰项 <a class="header-anchor" href="#技巧1-排除干扰项" aria-label="Permalink to &quot;技巧1：排除干扰项&quot;">​</a></h3><p><strong>方式</strong>：关键词1+空格+减号+关键词2，即 <code>关键词1 -关键词2</code></p><p><strong>功能</strong>：排除一些不想要的关键词</p><p><strong>示例</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>锤子 -锤子手机</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>示例中将在搜索结果排除与<code>锤子手机</code>相关的，只显示<code>锤子</code>本来的样子。</p><blockquote><p>经过百度搜索的测试，有的关键词能排除掉，有的并不好使</p></blockquote><h3 id="技巧2-精确搜索" tabindex="-1">技巧2：精确搜索 <a class="header-anchor" href="#技巧2-精确搜索" aria-label="Permalink to &quot;技巧2：精确搜索&quot;">​</a></h3><p><strong>方式</strong>：给关键词加双引号，<code>&quot;关键词&quot;</code></p><p><strong>功能</strong>：只搜索引号里的字，少一个字或者把字拆开都不行</p><p><strong>示例</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;达拉不崩吧&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>注意是英文的双引号</p></blockquote><h3 id="技巧3-指定网站内搜索" tabindex="-1">技巧3：指定网站内搜索 <a class="header-anchor" href="#技巧3-指定网站内搜索" aria-label="Permalink to &quot;技巧3：指定网站内搜索&quot;">​</a></h3><p><strong>方式</strong>：<code>site:域名 关键词</code></p><p><strong>功能</strong>：只搜索指定域名的内容</p><p><strong>示例</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>site:zhihu.com 前端</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>有一些站内自带的搜索并不好用，可以尝试这个搜索技巧。</p><h3 id="技巧4-指定文件格式" tabindex="-1">技巧4：指定文件格式 <a class="header-anchor" href="#技巧4-指定文件格式" aria-label="Permalink to &quot;技巧4：指定文件格式&quot;">​</a></h3><p><strong>方式</strong>：<code>filetype:文件格式 关键词</code></p><p><strong>示例</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filetype:avi 你懂的</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常见文件格式有<code>doc</code>、<code>pdf</code>、<code>ppt</code>等</p><h3 id="技巧5-指定在标题搜索" tabindex="-1">技巧5：指定在标题搜索 <a class="header-anchor" href="#技巧5-指定在标题搜索" aria-label="Permalink to &quot;技巧5：指定在标题搜索&quot;">​</a></h3><p><strong>方式</strong>：<code>intitle:关键词</code></p><p><strong>功能</strong>：搜索的关键词要出现在标题当中</p><h3 id="技巧6-指定在内容中搜索" tabindex="-1">技巧6：指定在内容中搜索 <a class="header-anchor" href="#技巧6-指定在内容中搜索" aria-label="Permalink to &quot;技巧6：指定在内容中搜索&quot;">​</a></h3><p><strong>方式</strong>：<code>intext:关键词</code>、<code>allintext:关键词1 关键词2</code>、<code>inurl:关键词2</code></p><h3 id="技巧7-多种搜索技巧叠加使用" tabindex="-1">技巧7：多种搜索技巧叠加使用 <a class="header-anchor" href="#技巧7-多种搜索技巧叠加使用" aria-label="Permalink to &quot;技巧7：多种搜索技巧叠加使用&quot;">​</a></h3><p><strong>示例</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>site:zhihu.com 前端 intitle:js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>多种技巧和关键词叠加使用，中间空格隔开。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>以上搜索技巧使用的符号均是英文符号。</p>',37)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
